import math

def prod2sum(a, b, c, d):
    sums = calculate_sums(a, b, c, d)
    product = sums[0] * sums[1]
    decomposed = decompose_product(product)
    return decomposed

def calculate_sums(a, b, c, d):
    sum1 = a**2 + b**2
    sum2 = c**2 + d**2
    return sum1, sum2

def decompose_product(product):
    solutions = []
    for e in range(int(math.sqrt(product)) + 1):
        f_squared = product - e**2
        f = int(math.sqrt(f_squared))
        if f**2 == f_squared:
            solutions.append([min(e, f), max(e, f)])
    return sorted(solutions)
